PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS user (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,emailVerified INTEGER NOT NULL DEFAULT 0,image TEXT,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session (id TEXT PRIMARY KEY,expiresAt INTEGER NOT NULL,token TEXT NOT NULL UNIQUE,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL,ipAddress TEXT,userAgent TEXT,userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON session(userId);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY,accountId TEXT NOT NULL,providerId TEXT NOT NULL,userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,accessToken TEXT,refreshToken TEXT,idToken TEXT,accessTokenExpiresAt INTEGER,refreshTokenExpiresAt INTEGER,scope TEXT,password TEXT,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS account_user_idx ON account(userId);
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY,identifier TEXT NOT NULL,value TEXT NOT NULL,expiresAt INTEGER NOT NULL,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS verification_identifier_idx ON verification(identifier);

CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE,full_name TEXT,email TEXT,phone TEXT,avatar_url TEXT,bio TEXT,role TEXT NOT NULL DEFAULT 'member',nfc_id TEXT UNIQUE,date_of_birth TEXT,department TEXT,emergency_contact TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT,event_type TEXT DEFAULT 'service',start_at TEXT,end_at TEXT,date_label TEXT,time_label TEXT,location TEXT,poster_url TEXT,capacity INTEGER DEFAULT 0,registration_deadline TEXT,is_free INTEGER DEFAULT 1,base_price REAL DEFAULT 0,category TEXT,department_id TEXT,expected_attendance INTEGER,budget_notes TEXT,status TEXT NOT NULL DEFAULT 'published',created_by TEXT,date TEXT,time TEXT,google_event_id TEXT,publish_google INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_packages(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,price REAL NOT NULL DEFAULT 0,capacity INTEGER DEFAULT 0,attendance_type TEXT DEFAULT 'full',includes_meals INTEGER DEFAULT 0,sort_order INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registrations(id TEXT PRIMARY KEY,user_id TEXT,event_id TEXT,package_id TEXT,ticket_type_id TEXT,event_title TEXT,package_name TEXT,package_price REAL DEFAULT 0,status TEXT DEFAULT 'confirmed',payment_status TEXT DEFAULT 'unpaid',attendee_id TEXT UNIQUE,qr_token TEXT UNIQUE,checked_in INTEGER DEFAULT 0,checked_in_at TEXT,bracelet_code TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS checkins(id TEXT PRIMARY KEY,registration_id TEXT NOT NULL,event_id TEXT,scanned_by TEXT,type TEXT NOT NULL DEFAULT 'entry',meal TEXT,day_date TEXT DEFAULT (date('now')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,leader_id TEXT,day_of_week TEXT,time_label TEXT,location TEXT,meeting_day TEXT,meeting_time TEXT,meeting_location TEXT,is_active INTEGER DEFAULT 1,member_count INTEGER DEFAULT 0,capacity INTEGER DEFAULT 0,image_url TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS group_members(id TEXT PRIMARY KEY,group_id TEXT NOT NULL,user_id TEXT NOT NULL,status TEXT DEFAULT 'pending',joined_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(group_id,user_id));
CREATE TABLE IF NOT EXISTS group_meetings(id TEXT PRIMARY KEY,group_id TEXT NOT NULL,date TEXT DEFAULT (date('now')),notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS group_attendance(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL,user_id TEXT NOT NULL,present INTEGER DEFAULT 1,UNIQUE(meeting_id,user_id));
CREATE TABLE IF NOT EXISTS group_announcements(id TEXT PRIMARY KEY,group_id TEXT NOT NULL,author_id TEXT,message TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sermons(id TEXT PRIMARY KEY,title TEXT NOT NULL,speaker TEXT,date TEXT,description TEXT,youtube_url TEXT,thumbnail_url TEXT,category TEXT,tags TEXT,published INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS livestream_config(id TEXT PRIMARY KEY,youtube_url TEXT,facebook_url TEXT,is_active INTEGER DEFAULT 0,next_stream_date TEXT,next_stream_title TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS social_media(id TEXT PRIMARY KEY,platform TEXT NOT NULL,url TEXT,is_active INTEGER DEFAULT 1,display_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS social_links(id TEXT PRIMARY KEY,platform TEXT NOT NULL,url TEXT,is_active INTEGER DEFAULT 1,sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS contact_messages(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,subject TEXT,message TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT,title TEXT NOT NULL,body TEXT,type TEXT DEFAULT 'info',read INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_transactions(id TEXT PRIMARY KEY,user_id TEXT,registration_id TEXT,session_id TEXT UNIQUE,amount REAL,currency TEXT DEFAULT 'ron',status TEXT DEFAULT 'initiated',payment_status TEXT DEFAULT 'pending',metadata TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bracelets(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,nfc_id TEXT UNIQUE,active INTEGER DEFAULT 1,assigned_to TEXT,assigned_at TEXT,lost_at TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bracelet_assignments(id TEXT PRIMARY KEY,bracelet_code TEXT NOT NULL,registration_id TEXT,user_id TEXT,assigned_at TEXT DEFAULT CURRENT_TIMESTAMP,released_at TEXT,assigned_by TEXT);
CREATE TABLE IF NOT EXISTS integration_tokens(id TEXT PRIMARY KEY,provider TEXT NOT NULL,account_id TEXT,tokens TEXT,access_token TEXT,refresh_token TEXT,expires_at TEXT,metadata TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,account_id));
CREATE TABLE IF NOT EXISTS service_plans(id TEXT PRIMARY KEY,external_id TEXT UNIQUE,title TEXT NOT NULL,service_type TEXT,scheduled_start TEXT,scheduled_end TEXT,raw_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_items(id TEXT PRIMARY KEY,service_plan_id TEXT NOT NULL,external_id TEXT,title TEXT NOT NULL,item_type TEXT,sort_order INTEGER DEFAULT 0,planned_duration INTEGER,raw_json TEXT,UNIQUE(service_plan_id,external_id));
CREATE TABLE IF NOT EXISTS service_volunteers(id TEXT PRIMARY KEY,service_plan_id TEXT NOT NULL,external_id TEXT,person_id TEXT,name TEXT,team TEXT,status TEXT DEFAULT 'scheduled',raw_json TEXT);
CREATE TABLE IF NOT EXISTS production_events(id TEXT PRIMARY KEY,service_plan_id TEXT,item_id TEXT,type TEXT NOT NULL,payload TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connector_devices(id TEXT PRIMARY KEY,device_key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,type TEXT NOT NULL,capabilities TEXT DEFAULT '[]',status TEXT DEFAULT 'offline',last_seen_at TEXT,metadata TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_live_state(id TEXT PRIMARY KEY DEFAULT 'current',service_plan_id TEXT,current_item_id TEXT,presentation TEXT,current_slide INTEGER,slide_count INTEGER,section TEXT,song TEXT,lyrics TEXT,timer_name TEXT,timer_seconds INTEGER,timer_running INTEGER DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_alerts(id TEXT PRIMARY KEY,severity TEXT DEFAULT 'info',source TEXT,message TEXT NOT NULL,resolved INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,user_id TEXT,action TEXT NOT NULL,target_type TEXT,target_id TEXT,metadata TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_dashboards(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT,is_default INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_widgets(id TEXT PRIMARY KEY,dashboard_id TEXT NOT NULL,widget_type TEXT NOT NULL,title TEXT,config TEXT DEFAULT '{}',x INTEGER DEFAULT 0,y INTEGER DEFAULT 0,w INTEGER DEFAULT 4,h INTEGER DEFAULT 3,sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS production_permissions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,capability TEXT NOT NULL,allowed INTEGER DEFAULT 0,UNIQUE(user_id,capability));
CREATE INDEX IF NOT EXISTS events_start_idx ON events(start_at);
CREATE INDEX IF NOT EXISTS registrations_event_idx ON registrations(event_id);
CREATE INDEX IF NOT EXISTS bracelets_code_idx ON bracelets(code);
